<script setup lang="ts">import type{CrmTicket}from"~/composables/useCrm";defineProps<{item:CrmTicket}>();defineEmits<{assign:[item:CrmTicket];transition:[item:CrmTicket,state:string]}>();</script><template><section class="crm-ticket-workspace"><header><div><span class="eyebrow">تیکت #{{item.public_id.toLocaleString('fa-IR')}}</span><h2>{{item.subject}}</h2><p>{{item.channel}} · {{item.display_name||'کاربر هفت‌سو'}}</p></div><span class="status-pill" :data-status="item.sla_state">{{item.sla_state}}</span></header><div class="crm-conversation"><article><strong>کاربر</strong><p>برای این موضوع نیاز به راهنمایی و پیگیری دارم.</p></article><article class="internal"><strong>یادداشت داخلی</strong><p>اطلاعات تماس در نمای کارشناس ماسک شده و تمام تغییرات ممیزی می‌شوند.</p></article></div><label>پاسخ یا یادداشت<textarea rows="4" placeholder="پاسخ را بنویسید…"></textarea></label><footer><button v-if="item.state==='open'" class="primary-button compact" @click="$emit('assign',item)">دریافت تیکت</button><button v-else class="primary-button compact" @click="$emit('transition',item,'resolved')">ثبت پاسخ و حل</button><button class="secondary-button compact" @click="$emit('transition',item,'waiting_customer')">منتظر پاسخ کاربر</button></footer></section></template>
